```typescript
export function useSiteRequirements() {
  const requirements = ref<Record<number, DailyRequirement>>({});
  const scheduleStore = useScheduleStore();
  const orgStore = useOrganizationStore();

  async function saveRequirements() {
    // Supabase에 저장
    const upsertData = [];
    for (let dayOfWeek = 0; dayOfWeek < 7; dayOfWeek++) {
      const req = requirements.value[dayOfWeek];

      for (const shift of orgStore.shifts) {
        if (shift.code === 'H') continue; // Holiday 제외

        const count = req[shift.code as keyof DailyRequirement] || 0;

        upsertData.push({
          organization_id: orgStore.organization!.id,
          shift_id: shift.id,
          day_of_week: dayOfWeek,
          required_count: count
        });
      }
    }

    const { error } = await supabase
      .from('site_requirements')
      .upsert(upsertData, {
        onConflict: 'organization_id,shift_id,day_of_week'
      });

    if (error) {
      console.error('Error saving site requirements:', error);
      throw error;
    }

    // Schedule Store 업데이트
    scheduleStore.setSiteRequirements(requirements.value);
  }

  return { requirements, loadRequirements, saveRequirements };
}
