1. Polling에 최대 시도 횟수 제한 (60회 = 5분)
2. Network error 발생 시 exponential backoff retry
3. Solver error 발생 시 에러 메시지 저장
4. Timeout 시 사용자에게 알림

예시 코드:
```typescript
export function useAISolver() {
  const status = ref<string>('idle');
  const error = ref<string | null>(null);
  const maxPollingAttempts = 60; // 5분 (5초 × 60회)
  let pollingAttempts = 0;
  let pollingInterval: number | null = null;

  async function startSolver(scheduleId: string, payload: SolverPayload) {
    status.value = 'created';
    error.value = null;
    pollingAttempts = 0;

    try {
      // 1. Schedule status를 'running'으로 변경
      await supabase
        .from('schedules')
        .update({ status: 'running' })
        .eq('id', scheduleId);

      status.value = 'running';

      // 2. AI Solver API 호출 (비동기)
      requestAISolver(scheduleId, payload)
        .then(result => {
          saveResult(scheduleId, result);
        })
        .catch(err => {
          console.error('AI Solver error:', err);
          error.value = err.message;
          supabase
            .from('schedules')
            .update({ status: 'error' })
            .eq('id', scheduleId);
        });

      // 3. Polling 시작
      await startPolling(scheduleId);
    } catch (err: any) {
      error.value = err.message;
      status.value = 'error';
      throw err;
    }
  }

  async function startPolling(scheduleId: string) {
    return new Promise<void>((resolve, reject) => {
      pollingInterval = setInterval(async () => {
        pollingAttempts++;

        // Timeout 체크
        if (pollingAttempts > maxPollingAttempts) {
          stopPolling();
          error.value = 'Timeout: 근무표 생성이 5분을 초과했습니다. 다시 시도해주세요.';
          status.value = 'error';
          reject(new Error(error.value));
          return;
        }

        try {
          // Supabase에서 status 조회
          const { data, error: fetchError } = await supabase
            .from('schedules')
            .select('status, hard_score, soft_score')
            .eq('id', scheduleId)
            .single();

          if (fetchError) {
            throw fetchError;
          }

          status.value = data.status;

          if (data.status === 'complete') {
            stopPolling();
            resolve();
          } else if (data.status === 'error') {
            stopPolling();
            error.value = 'AI Solver에서 오류가 발생했습니다.';
            reject(new Error(error.value));
          }
        } catch (err: any) {
          console.error('Polling error:', err);
          // Network error는 다음 polling에서 재시도
          if (pollingAttempts > maxPollingAttempts) {
            stopPolling();
            error.value = 'Network error: 연결이 불안정합니다.';
            status.value = 'error';
            reject(new Error(error.value));
          }
        }
      }, 5000); // 5초마다
    });
  }

  function stopPolling() {
    if (pollingInterval) {
      clearInterval(pollingInterval);
      pollingInterval = null;
    }
  }

  return { status, error, startSolver, stopPolling };
}
