<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useOrganizationStore } from '@/stores/organization';
import { useScheduleStore } from '@/stores/schedule';
import { loadScheduleAssignments, updateScheduleAssignment } from '@/api/schedule';
import { getDaysInMonth, getLastDaysOfPreviousMonth } from '@/utils/date';
import type { AssignmentMap, GridColumn } from '@/types/schedule';

const route = useRoute();
const router = useRouter();
const orgStore = useOrganizationStore();
const scheduleStore = useScheduleStore();

const scheduleId = ref<string>('');
const schedule = ref<any>(null);
const employees = computed(() => orgStore.employees);
const dates = ref<GridColumn[]>([]);
const assignments = ref<AssignmentMap>({});
const changedCells = ref<Set<string>>(new Set()); // 변경된 셀 추적

onMounted(async () => {
  scheduleId.value = route.query.scheduleId as string;

  if (!scheduleId.value) {
    window.$message.error('잘못된 접근입니다.');
    router.push('/schedule/step1');
    return;
  }

  // 1. Employees 로드
  if (orgStore.employees.length === 0) {
    await orgStore.loadEmployees();
  }

  // 2. Dates 생성
  const month = scheduleStore.basicInfo!.month;
  const lastMonth = getLastDaysOfPreviousMonth(month, 5);
  const thisMonth = getDaysInMonth(month);
  dates.value = [...lastMonth, ...thisMonth];

  // 3. Schedule 및 Assignments 로드
  const result = await loadScheduleAssignments(scheduleId.value);
  schedule.value = result.schedule;
  assignments.value = result.assignments;
});

function handleAssignmentUpdate(payload: { employeeId: string; date: string; shiftCode: string }) {
  assignments.value[payload.employeeId][payload.date] = payload.shiftCode;
  changedCells.value.add(`${payload.employeeId}_${payload.date}`);
}

async function handleSave() {
  if (changedCells.value.size > 0) {
    // 변경된 셀만 Supabase에 업데이트
    for (const key of changedCells.value) {
      const [employeeId, date] = key.split('_');
      const shiftCode = assignments.value[employeeId][date];
      await updateScheduleAssignment(scheduleId.value, employeeId, date, shiftCode);
    }

    // Schedule status를 'changed'로 업데이트
    await supabase
      .from('schedules')
      .update({ status: 'changed' })
      .eq('id', scheduleId.value);

    window.$message.success('저장되었습니다.');
  }

  router.push('/');
}
</script>
