```typescript
// api/schedule.ts
export async function loadScheduleAssignments(scheduleId: string) {
  // Schedule 조회
  const { data: schedule, error: scheduleError } = await supabase
    .from('schedules')
    .select('*')
    .eq('id', scheduleId)
    .single();

  if (scheduleError) throw scheduleError;

  // Schedule Assignments 조회
  const { data: assignmentRows, error: assignmentsError } = await supabase
    .from('schedule_assignments')
    .select(`
      employee_id,
      date,
      shifts (code)
    `)
    .eq('schedule_id', scheduleId);

  if (assignmentsError) throw assignmentsError;

  // AssignmentMap으로 변환
  const assignments: AssignmentMap = {};
  for (const row of assignmentRows) {
    if (!assignments[row.employee_id]) {
      assignments[row.employee_id] = {};
    }
    assignments[row.employee_id][row.date] = row.shifts.code;
  }

  return { schedule, assignments };
}

export async function updateScheduleAssignment(
  scheduleId: string,
  employeeId: string,
  date: string,
  shiftCode: string
) {
  // shift_id 조회
  const { data: shift } = await supabase
    .from('shifts')
    .select('id')
    .eq('code', shiftCode)
    .single();

  if (!shift) throw new Error('Invalid shift code');

  // Update or Insert
  const { error } = await supabase
    .from('schedule_assignments')
    .upsert({
      schedule_id: scheduleId,
      employee_id: employeeId,
      shift_id: shift.id,
      date,
    }, {
      onConflict: 'schedule_id,employee_id,date'
    });

  if (error) throw error;
}
