// router/guards.ts
import type { NavigationGuardNext, RouteLocationNormalized } from 'vue-router';
import { useScheduleStore } from '@/stores/schedule';

export function stepProgressGuard(
  to: RouteLocationNormalized,
  from: RouteLocationNormalized,
  next: NavigationGuardNext
) {
  const scheduleStore = useScheduleStore();

  // Step 2 접근 시 Step 1 완료 확인
  if (to.path === '/schedule/step2') {
    if (!scheduleStore.basicInfo?.month) {
      window.$message.warning('먼저 기본 정보를 입력해주세요.');
      next('/schedule/step1');
      return;
    }
  }

  // Step 3 접근 시 Step 2 완료 확인
  if (to.path === '/schedule/step3') {
    if (!scheduleStore.basicInfo?.month) {
      next('/schedule/step1');
      return;
    }
    // siteRequirements 확인은 optional (사용자가 저장하지 않을 수도 있음)
  }

  // Step 4 접근 시 scheduleId 필수
  if (to.path === '/schedule/step4') {
    if (!to.query.scheduleId) {
      window.$message.warning('잘못된 접근입니다.');
      next('/schedule/step3');
      return;
    }
  }

  next();
}

// router/index.ts
import { stepProgressGuard } from './guards';

router.beforeEach((to, from, next) => {
  // Auth guard
  if (to.meta.requiresAuth && !authStore.isAuthenticated) {
    next('/login');
    return;
  }

  // Step progress guard
  if (to.path.startsWith('/schedule/step')) {
    stepProgressGuard(to, from, next);
    return;
  }

  next();
});
