const rowStats = computed(() => {
  const cache = new Map();

  return Object.entries(assignments.value).reduce((acc, [employeeId, empAssignments]) => {
    const cacheKey = JSON.stringify(empAssignments);

    if (!cache.has(cacheKey)) {
      const stat: RowStat = { D: 0, E: 0, N: 0, total: 0 };
      Object.values(empAssignments).forEach(shiftCode => {
        if (shiftCode === 'D') stat.D++;
        if (shiftCode === 'E') stat.E++;
        if (shiftCode === 'N') stat.N++;
        if (shiftCode !== 'O') stat.total++;
      });
      cache.set(cacheKey, stat);
    }

    acc[employeeId] = cache.get(cacheKey)!;
    return acc;
  }, {} as Record<string, RowStat>);
});
